import{_ as a,o as i,c as e,an as n}from"./chunks/framework.WiyRdOF4.js";const k=JSON.parse('{"title":"Get started","description":"","frontmatter":{},"headers":[],"relativePath":"get_started.md","filePath":"get_started.md","lastUpdated":null}'),t={name:"get_started.md"};function p(l,s,o,h,r,d){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="Get-started" tabindex="-1">Get started <a class="header-anchor" href="#Get-started" aria-label="Permalink to &quot;Get started {#Get-started}&quot;">​</a></h1><p>MicroclimateMapper.jl computes microclimates with <a href="https://biophysicalecology.github.io/Microclimate.jl/dev" target="_blank" rel="noreferrer">Microclimate.jl</a> for points or grids, taking the weather, terrain, vegetation, soil and surface from spatial data sets.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Pkg</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">add</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(url </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://github.com/BiophysicalEcology/MicroclimateMapper.jl&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Data sets are downloaded once and kept in a folder of your choice:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">ENV</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RASTERDATASOURCES_PATH&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> joinpath</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">homedir</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(), </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;spatial_data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h2 id="A-desert-and-a-mountain" tabindex="-1">A desert and a mountain <a class="header-anchor" href="#A-desert-and-a-mountain" aria-label="Permalink to &quot;A desert and a mountain {#A-desert-and-a-mountain}&quot;">​</a></h2><p>Palm Springs, California, lies at the foot of Mount San Jacinto, 13 km away and 3 km higher. The desert iguana of <a href="https://biophysicalecology.github.io/BiophysicalBehaviour.jl/dev/tutorials/lizard" target="_blank" rel="noreferrer">A lizard&#39;s day</a> lives on the desert floor.</p><p>The point model is a <code>MicroModel</code> of Microclimate.jl: soil depths, heights above ground, soil properties and snow, see its <a href="https://biophysicalecology.github.io/Microclimate.jl/dev/manual/configuring_the_model" target="_blank" rel="noreferrer">Configuring the model</a>.</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> MicroclimateMapper, Microclimate, RasterDataSources, Rasters, Dates, Unitful</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Microclimate</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> example_soil_profile, example_soil_properties_model, example_soil_hydraulic_model</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">depths </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2.5</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">15.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">20.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">30.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">200.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cm&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">heights </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.01</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;m&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">micro_model </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> MicroModel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(; depths, heights,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    soil_properties_model </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> example_soil_properties_model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    soil_hydraulic_model </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> example_soil_hydraulic_model</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    snow_model </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> SnowModel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(),</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>A <a href="/MicroclimateMapper.jl/previews/PR41/api#MicroclimateMapper.MicroMapModel"><code>MicroMapModel</code></a> adds the data sets. Here the weather is the CRU CL 2.0 climatology, soil moisture is the CPC climatology, and terrain comes from SRTM:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">model </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> MicroMapModel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(; micro_model,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    dem_source </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SRTM,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    weather_source </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CRUCL2,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    soil_moisture_source </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CPCSoil,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    surface_albedo_source </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.15</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    roughness_height_source </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0.004</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;m&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>A <a href="/MicroclimateMapper.jl/previews/PR41/api#MicroclimateMapper.MicroVectorProblem"><code>MicroVectorProblem</code></a> gives it places and dates. Points are <code>(longitude, latitude)</code>:</p><div class="language-@example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sites = [(-116.545, 33.830), (-116.679, 33.814)]   # Palm Springs, San Jacinto Peak</span></span>
<span class="line"><span>problem = MicroVectorProblem(; model, points = sites,</span></span>
<span class="line"><span>    dates = Date(2000, 1, 1):Day(1):Date(2000, 12, 31),</span></span>
<span class="line"><span>    soil_profile = example_soil_profile(depths),</span></span>
<span class="line"><span>    init = (; soil_moisture = fill(0.2, length(depths)), snow_depth = 0.0u&quot;cm&quot;),</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span>cache = init(problem)     # loads the data</span></span>
<span class="line"><span>output = solve!(cache)    # solves every point</span></span></code></pre></div><p><code>solve(problem)</code> does both. The output is a <code>RasterStack</code>. Each layer has named dimensions: <code>point</code>, <code>Ti</code> (time), and <code>depth</code> or <code>height</code> where they apply. A monthly climatology gives one representative day per month, hour by hour.</p><div class="language-@example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>soil_surface = output.soil_temperature[depth = 1]</span></span>
<span class="line"><span>fig = Figure(size = (800, 300)) # hide</span></span>
<span class="line"><span>axes = [Axis(fig[1, i]; title = name, xlabel = &quot;Hour of the representative day&quot;, ylabel = i == 1 ? &quot;Soil surface (°C)&quot; : &quot;&quot;) # hide</span></span>
<span class="line"><span>        for (i, name) in enumerate((&quot;Palm Springs&quot;, &quot;San Jacinto Peak&quot;))] # hide</span></span>
<span class="line"><span>linkyaxes!(axes...) # hide</span></span>
<span class="line"><span>for (i, ax) in enumerate(axes) # hide</span></span>
<span class="line"><span>    for (m, label) in ((1, &quot;January&quot;), (7, &quot;July&quot;)) # hide</span></span>
<span class="line"><span>        lines!(ax, 0:23, celsius.(collect(soil_surface[point = i])[(m - 1) * 24 .+ (1:24)]); label) # hide</span></span>
<span class="line"><span>    end # hide</span></span>
<span class="line"><span>    i == 1 &amp;&amp; axislegend(ax; position = :lt) # hide</span></span>
<span class="line"><span>end # hide</span></span>
<span class="line"><span>fig # hide</span></span></code></pre></div><p>The weather is the same coarse climatology at both sites. The difference comes from the elevation in the DEM, which corrects the air temperature, pressure and radiation for each point:</p><div class="language-@example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>terrain(cache).elevation</span></span></code></pre></div><div class="language-@example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>markdown_table([&quot;&quot;, &quot;Palm Springs&quot;, &quot;San Jacinto Peak&quot;], [ # hide</span></span>
<span class="line"><span>    (&quot;hottest soil surface (°C)&quot;, maximum(celsius.(soil_surface[point = 1])), maximum(celsius.(soil_surface[point = 2]))), # hide</span></span>
<span class="line"><span>    (&quot;deepest snow (cm)&quot;, maximum(ustrip.(u&quot;cm&quot;, output.snow_depth[point = 1])), maximum(ustrip.(u&quot;cm&quot;, output.snow_depth[point = 2]))), # hide</span></span>
<span class="line"><span>]) # hide</span></span></code></pre></div><h2 id="A-map" tabindex="-1">A map <a class="header-anchor" href="#A-map" aria-label="Permalink to &quot;A map {#A-map}&quot;">​</a></h2><p>The same model over a grid is a <a href="/MicroclimateMapper.jl/previews/PR41/api#MicroclimateMapper.MicroRasterProblem"><code>MicroRasterProblem</code></a>: an area and a grid to solve on. Here the grid is that of CRU CL 2.0 itself, 10 arcminutes, over southern California:</p><div class="language-@example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>using Rasters.Extents: Extent</span></span>
<span class="line"><span>area = Extent(X = (-118.5, -115.5), Y = (32.8, 35.3))</span></span>
<span class="line"><span>grid_model = MicroMapModel(; micro_model, dem_source = CRUCL2, weather_source = CRUCL2,</span></span>
<span class="line"><span>    soil_moisture_source = CPCSoil, surface_albedo_source = 0.15, roughness_height_source = 0.004u&quot;m&quot;,</span></span>
<span class="line"><span>    compute_terrain = false)</span></span>
<span class="line"><span>grid = MicroRasterProblem(; model = grid_model, area,</span></span>
<span class="line"><span>    template = load_template(CRUCL2, area),</span></span>
<span class="line"><span>    dates = Date(2000, 1, 1):Day(1):Date(2000, 12, 31),</span></span>
<span class="line"><span>    soil_profile = example_soil_profile(depths),</span></span>
<span class="line"><span>    init = (; soil_moisture = fill(0.2, length(depths)), snow_depth = 0.0u&quot;cm&quot;),</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span>maps = solve(grid)</span></span>
<span class="line"><span>nothing # hide</span></span></code></pre></div><div class="language-@example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hottest = maximum(maps.soil_temperature[depth = 1]; dims = Ti)[Ti = 1]</span></span>
<span class="line"><span>snow = maximum(maps.snow_depth; dims = Ti)[Ti = 1]</span></span>
<span class="line"><span>map_figure(( # hide</span></span>
<span class="line"><span>    (celsius.(hottest), &quot;Hottest soil surface (°C)&quot;, :thermal, &quot;°C&quot;), # hide</span></span>
<span class="line"><span>    (ustrip.(u&quot;cm&quot;, snow), &quot;Deepest snow (cm)&quot;, Reverse(:ice), &quot;cm&quot;), # hide</span></span>
<span class="line"><span>);  sites = (&quot;Palm Springs&quot; =&gt; sites[1],)) # hide</span></span></code></pre></div><p>At 18 km a cell averages mountain and desert, so the cell that contains Palm Springs is far cooler, and snowier, than the town. A finer DEM resolves them, at more cost, see <a href="./tutorials/maps">Maps</a>.</p><h2 id="Another-data-set" tabindex="-1">Another data set <a class="header-anchor" href="#Another-data-set" aria-label="Permalink to &quot;Another data set {#Another-data-set}&quot;">​</a></h2><p>Changing the weather is one keyword. WorldClim is another monthly climatology, for 1970–2000 where CRU CL 2.0 is for 1961–1990, with different variables and grids:</p><div class="language-@example vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">@example</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>worldclim = MicroMapModel(; micro_model, dem_source = SRTM, weather_source = WorldClim{Climate},</span></span>
<span class="line"><span>    soil_moisture_source = CPCSoil, surface_albedo_source = 0.15, roughness_height_source = 0.004u&quot;m&quot;)</span></span>
<span class="line"><span>other = solve(MicroVectorProblem(; model = worldclim, points = sites,</span></span>
<span class="line"><span>    dates = Date(2000, 1, 1):Day(1):Date(2000, 12, 31),</span></span>
<span class="line"><span>    soil_profile = example_soil_profile(depths),</span></span>
<span class="line"><span>    init = (; soil_moisture = fill(0.2, length(depths)), snow_depth = 0.0u&quot;cm&quot;)))</span></span>
<span class="line"><span>markdown_table([&quot;&quot;, &quot;CRU CL 2.0&quot;, &quot;WorldClim&quot;], [ # hide</span></span>
<span class="line"><span>    (&quot;hottest soil surface at Palm Springs (°C)&quot;, maximum(celsius.(soil_surface[point = 1])), maximum(celsius.(other.soil_temperature[point = 1, depth = 1]))), # hide</span></span>
<span class="line"><span>    (&quot;deepest snow on San Jacinto Peak (cm)&quot;, maximum(ustrip.(u&quot;cm&quot;, output.snow_depth[point = 2])), maximum(ustrip.(u&quot;cm&quot;, other.snow_depth[point = 2]))), # hide</span></span>
<span class="line"><span>]) # hide</span></span></code></pre></div><p>WorldClim publishes the elevation of its grid (<code>WorldClim{Elevation}</code> in RasterDataSources.jl), but the WorldClim binding does not read it yet, so its air temperatures are not yet corrected to the elevation of each point, see <a href="/MicroclimateMapper.jl/previews/PR41/manual/terrain#Elevation">Terrain and atmosphere</a>. Daily and hourly data sets, such as gridMET, NCEP and ERA5, are swapped in the same way and solve every day in turn, see <a href="./tutorials/swap_data">Swapping data sets</a>. See <a href="./manual/data_sources">One keyword per data set</a> for how this works, and <a href="./manual/forcing_data">Forcing data sets</a> for the choices.</p><h2 id="Where-next" tabindex="-1">Where next <a class="header-anchor" href="#Where-next" aria-label="Permalink to &quot;Where next {#Where-next}&quot;">​</a></h2><ul><li><p><a href="./interactive">Interactive app</a>: pick a place on a map, swap data sets, plot the results and copy the script that reproduces them.</p></li><li><p><a href="./tutorials/points">Points</a> and <a href="./tutorials/maps">Maps</a> for more of each.</p></li><li><p><a href="./manual/spatial_stack">Built on Rasters and DimensionalData</a> for what can be done with the output.</p></li><li><p><a href="./manual/introduction">Introduction</a> for the design of the package.</p></li></ul>`,29)])])}const u=a(t,[["render",p]]);export{k as __pageData,u as default};
